SET NAMES utf8mb4;
-- 敏捷冲刺管理 (tplFNqzdFo0qK)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"冲刺（Sprint）是Scrum团队使用的短周期迭代，用于生成产品。在冲刺中，复杂的项目会被分解成小块。\\"冲刺使项目更易管理，让团队能更快、更频繁地交付高质量工作，并提供更大的灵活性来适应变化。\\"通过不同的视图，这个冲刺管理模板可以过滤任务、跟踪状态、展示产品路线图，帮助你：\\n\\n跟踪进度：多种视图提供清晰的概览，可视化进度。你可以看到从冲刺规划到冲刺结束的所有内容。\\n\\n高效协作：这个平台可用于分配任务、提出请求和发布共享项目的更新。\\n\\n此模板非常适合使用Scrum管理方法的公司。它不仅是产品经理、开发人员的平台，也适用于设计师、运营人员等。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplFNqzdFo0qK');

-- 产品发布计划 (tplDu36PN3yMt)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"产品发布计划也称为\\"项目计划\\"或\\"交付计划\\"，它描述了：\\n• 将要处理的主要项目\\n• 未来特定冲刺的目标功能\\n• 何时发布输出\\n\\n此模板通常由产品和工程团队使用，以确保成员对项目保持一致和可视化。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplDu36PN3yMt');

-- 客户项目管理 (tpl9Qy1d3BYC4)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"此模板非常适合咨询公司、律师事务所和销售团队，因为它可以帮助计算需要补偿的工作时间，让你对项目进度有一个高层次的概览，并创建一个协作平台。\\n\\n使用此模板的好处：\\n\\n可追溯性：项目的所有信息，包括开始/结束日期、负责人、客户联系人和时间线、进度状态都可以在这里跟踪，确保相关团队成员了解项目的一切，以便他们能够遵守时间限制并全力以赴。\\n\\n向客户收费：从创意生成到脚本编写和视频制作，整个记录和流程都可以在这里管理。这也是团队成员的协作平台，他们可以将所有材料和交付成果放在一个地方。\\n\\n协作：在这一个地方为利益相关者分配任务、发布共享项目的更新和文件，确保所有事情都得到安排和协调。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tpl9Qy1d3BYC4');

-- 视频制作管理 (tplkKZVZhoLcR)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"你可以使用此模板管理视频制作工作流程。模板表单可用于提出视频请求，看板用于管理联系人，仪表盘用于创建制作运行情况的概览。\\n\\n使用此模板的好处：\\n\\n可追溯性：通过过滤状态、优先级、类别等，你可以在这里跟踪所有制作项目，了解包括进度和阻塞原因在内的更新。\\n\\n流程管理：从创意生成到脚本编写和视频制作，整个记录和流程都可以在这里管理。这也是团队成员的协作平台，他们可以将所有材料和交付成果放在一个地方。\\n\\n此模板非常适合营销、广告、视频工作室、网红团队以及许多其他从事数字视频制作任务的组织。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplkKZVZhoLcR');

-- 单项目管理 (tplV4w28zRR5y)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"将截止日期、利益相关者、预算等汇集在一个地方。计划、管理和跟踪项目的每个方面，确保不会遗漏任何内容。\\n\\n使用此模板的好处：\\n\\n设置里程碑和时间线：通过不同的视图了解所有项目阶段的流程。这样你可以关注即将到来的截止日期，并自动通知任务负责人逾期项目。\\n\\n组织任务：为项目的每个阶段或类别构建组，并细化它们以反映团队或个人所有权。\\n\\n实现完全可见性：根据状态和优先级对任务进行分类，使整个团队都能访问其工作的实时真实来源。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplV4w28zRR5y');

-- 内容日历 (tpls68R8XJQXH)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"此模板用作工作流工具和创作过程中交付成果的中心枢纽，适用于营销、广告、视频、网红团队以及许多其他从事内容制作任务的组织。使用此模板，你可以：\\n\\n管理多个日程：通过使用甘特图视图，可以更轻松地围绕截止日期规划工作。\\n\\n明确分配任务：信息和资源可以在此日历中清晰列出，例如项目主题、内容类型、状态、发布渠道等。此外，内置通知将确保受让人了解他们的任务和相关资源。\\n\\n查看项目详情：此日历数据库让协作者可以将所有作品和重要数据放在这里，确保可以跟踪每个表现。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tpls68R8XJQXH');

-- 房产CRM (tplr0y8Z82JCy)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"此模板可用作管理房地产业务运营的集中数据库。你可以与潜在客户及其所需房产保持联系，存储房地产详细信息，在这里管理经纪人工作流程。\\n\\n使用此模板的好处：\\n\\n集中管理所有房产：在一个地方管理有关房产的所有信息，包括位置、房产详情、房产照片、价格等。\\n\\n捕获和管理潜在客户：使用可自定义的表单捕获客户线索。将每个线索与特定且合适的房产匹配，以获得成交机会。\\n\\n审查并分配任务给经纪人：即时可视化，以便跟踪经纪人工作量并相应地将可用经纪人与客户联系起来。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplr0y8Z82JCy');

-- 营销活动管理 (tplMQR44UebkN)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"从规划到执行，营销活动涉及几个不同的阶段，因此很复杂。此外，点击和转化的结果审查是一个混乱的过程。如果有一个解决方案可以跟踪营销活动的所有需求，那就太好了！\\n\\n使用此模板，你可以轻松跟踪和管理每个营销活动的组织进度。此外，你还可以通过跟踪从支出到点击和转化的所有内容来评估活动的表现。\\n\\n此模板非常适合小型企业和初创公司，并且足够灵活以适应大型企业。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplMQR44UebkN');

-- 用户研究管理 (tpl2h5oXUlARv)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"用户研究的任务是与用户交谈，收集他们的反馈，并将这些反馈转化为可在产品设计过程中使用的可操作见解。\\n\\n此模板用于帮助大规模实施反馈收集工作。有1个仪表盘和4个主要表格：\\n\\n研究仪表盘：提供研究会话状态和见解的概览。\\n用户：计划进行会话的用户列表。\\n研究：将所有研究材料（包括报告和会议记录）汇集在一起。\\n会话计划：帮助记录会话日期、时间和联系人。\\n洞见要点：将所有事实、见解、机会汇集在一起以做出决策。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tpl2h5oXUlARv');

-- 项目管理 (tplED3FVnX8U6)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"跨多个团队和部门规划、跟踪和管理复杂项目始终是一个挑战。通过使用此模板，你可以在项目管理方面做得更好：\\n\\n任务管理：通过展示任务的截止日期、不同视图、文件、团队评论、日历和受让人，此模板确保团队成员了解任务详情，让他们知道做什么、何时做以及如何做。\\n\\n协作：任务可以集中在一个地方并分发给不同的组织，以便不同的团队成员可以通过在同一文档窗口上工作来协作。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplED3FVnX8U6');

-- 内部需求管理 (tpl5X7cPb8R0R)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"通过营销部门的活动工作流模板，实现同样的透明度、可扩展性和灵活性。\\n\\n使用此模板的好处：\\n\\n集中所有内部和外部请求：利用表单收集你需要的所有相关信息，并将所有内容组织到一个统一的空间中。\\n\\n通过数据驱动的决策推动成功：使用真实数据为未来计划做出明智决策，以持续改进和增强你的工作。\\n\\n与外部利益相关者无缝协作：与供应商轻松协作，使信息易于访问，并在正确的时间与正确的团队共享正确的信息。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tpl5X7cPb8R0R');

-- 库存管理 (tplVaVrnBrUZT)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"对企业来说，库存管理并不容易。此模板是帮助跟踪库存、采购和销售的好工具。通过记录产品的详细信息，如价格、位置、图片、采购和销售订单等，你的企业可以跟踪库存水平。通过不同的视图，可以轻松展示每个产品的表现。如果你想优化库存，可以比较哪些产品销售得更快。\\n\\n小型本地企业和大型企业都可以依靠此模板，它足够灵活，可以优化以支持业务扩展。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplVaVrnBrUZT');

-- OKR追踪 (tpluf3QLJ4asF)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"此模板用于设定目标。它是跟踪团队中每个人OKR的有用工具。调查显示，提高员工绩效的方法之一是鼓励他们预先设定目标。使用此模板，你可以为团队创建一个公共场所，以频繁设置、跟踪和重新评估OKR，并使每个人都能看到团队的日常工作，提高他们在过程中的参与度。\\n\\n它非常适合初创公司和旨在快速增长或在组织中创建一致性的公司。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tpluf3QLJ4asF');

-- 课程排期 (tplvV9Y2mJvbS)
UPDATE `${table.prefix}node_desc` SET description = '{"text":"排课是一个复杂的过程，涉及检查多个工作表和准备时间表。为了有效地安排日程，将所有信息（包括课程、教室、班级）集中到一个直观的系统中非常重要。\\n\\n此模板的一些关键功能包括：\\n\\n• 课程、班级和教室的重要信息可以在相应级别汇总。\\n• 日历视图清晰地展示班级表。\\n• 一个\\"全部教室\\"表，允许教务处将教室分配给不同的班级。"}'
WHERE node_id = (SELECT node_id FROM `${table.prefix}template` WHERE template_id = 'tplvV9Y2mJvbS');

SET NAMES utf8mb4;
UPDATE `${table.prefix}node_desc`
SET description = JSON_SET(
    description,
    '$.render',
    REPLACE(
        REPLACE(JSON_UNQUOTE(JSON_EXTRACT(description, '$.render')), 'u003c', '<'),
        'u003e', '>'
    )
)
WHERE JSON_UNQUOTE(JSON_EXTRACT(description, '$.render')) LIKE '%u003c%';

